const returnedByProduct = `-- name: ReturnedByProduct :many
SELECT i.product_id, CAST(COALESCE(SUM(i.qty_base), 0) AS DECIMAL(36,12)) AS total
FROM sales_return_items i JOIN sales_returns s ON s.id = i.return_id
WHERE s.branch_id = ? AND s.status = 'confirmed'
  AND s.return_date >= ? AND s.return_date <= ?
GROUP BY i.product_id
`

type ReturnedByProductParams struct {
	BranchID int64
	FromAt   time.Time
	ToAt     time.Time
}

type ReturnedByProductRow struct {
	ProductID int64
	Total     float64
}

// Sums returned base qty per product over confirmed returns dated within the
// inclusive day range (bounds are day-start instants computed in Go).
func (q *Queries) ReturnedByProduct(ctx context.Context, arg ReturnedByProductParams) ([]ReturnedByProductRow, error) {
	rows, err := q.db.QueryContext(ctx, returnedByProduct, arg.BranchID, arg.FromAt, arg.ToAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReturnedByProductRow{}
	for rows.Next() {
		var i ReturnedByProductRow
		if err := rows.Scan(&i.ProductID, &i.Total); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const returnedQty = `-- name: ReturnedQty :one
SELECT CAST(COALESCE(SUM(i.qty_base), 0) AS DECIMAL(36,12)) AS total
FROM sales_return_items i
JOIN sales_returns s ON s.id = i.return_id
WHERE s.sales_order_id = ? AND s.status = 'confirmed'
  AND i.product_id = ? AND i.variant_id = ?
`

type ReturnedQtyParams struct {
	SalesOrderID int64
	ProductID    int64
	VariantID    int64
}

// Sums confirmed-returned base qty for one SO line position. Only confirmed
// returns count — drafts reserve nothing.
func (q *Queries) ReturnedQty(ctx context.Context, arg ReturnedQtyParams) (float64, error) {
	row := q.db.QueryRowContext(ctx, returnedQty, arg.SalesOrderID, arg.ProductID, arg.VariantID)
	var total float64
	err := row.Scan(&total)
	return total, err
}

